type LabEvidenceCardProps = {
  className?: string;
  question?: string;
  showSource?: boolean;
  state?: "Error";
};

function LabEvidenceCard({ className, question = "What evidence supports this answer?", showSource = true, state = "Error" }: LabEvidenceCardProps) {
  return (
    <div className={className || '[word-break:break-word] bg-[var(--lab-surface,#f7f7fc)] content-stretch flex flex-col font-["Inter:Regular"] font-normal gap-[var(--lab-gap,12px)] items-start leading-[1.5] not-italic p-[var(--lab-padding,24px)] relative rounded-[var(--lab-radius,16px)] text-[16px] w-[360px]'} data-node-id="57:23">
      <p className="relative shrink-0 text-[color:var(--lab-error,#a52639)] w-full" data-node-id="57:24">
        Error
      </p>
      <p className="relative shrink-0 text-[color:var(--lab-text,#11142b)] w-full" data-node-id="57:25">
        {question}
      </p>
      <p className="relative shrink-0 text-[color:var(--lab-text,#11142b)] w-full" data-node-id="57:26">
        We could not load this source. Try again or open the original.
      </p>
      {showSource && (
        <p className="relative shrink-0 text-[color:var(--lab-accent,#2448ff)] w-full" data-node-id="57:27">
          Open original source
        </p>
      )}
    </div>
  );
}
